<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import axios from 'axios';
import {Search,MessageSquare} from '@lucide/vue';
import MobileIdentityAvatar from './MobileIdentityAvatar.vue';
import MobilePersonProfile from './MobilePersonProfile.vue';
import {formatPhoneForDisplay} from '../utils/phoneDisplay.js';
const props=defineProps({apiBase:String,sessionToken:String,userId:[String,Number],agencyId:[String,Number],visible:{type:Boolean,default:true},initialSuite:{type:String,default:'providers'}});
const emit=defineEmits(['message','compose-email','add-contact']);
const suite=ref(props.initialSuite),searchOpen=ref(false),query=ref(''),agency=ref(''),data=ref({providers:[],schoolStaff:[],agencies:[]}),saved=ref([]),profile=ref(null),loading=ref(false),error=ref('');let version=0,loadedAt=0;
const config=()=>({headers:{'X-Quick-View-Session':props.sessionToken},withCredentials:true});
const rows=computed(()=>{const source=suite.value==='saved'?saved.value:suite.value==='school_staff'?data.value.schoolStaff:data.value.providers;const q=query.value.trim().toLowerCase();return(source||[]).filter(row=>(!agency.value||Number(row.agencyId)===Number(agency.value))&&(!q||[row.displayName,row.name,row.email,row.credential,row.schoolName,row.agencyName].some(value=>String(value||'').toLowerCase().includes(q))));});
const agencies=computed(()=>data.value.agencies?.length?data.value.agencies:[...new Map([...(data.value.providers||[]),...(data.value.schoolStaff||[])].filter(row=>row.agencyId).map(row=>[Number(row.agencyId),{id:row.agencyId,name:row.agencyName}])).values()]);
const phone=row=>formatPhoneForDisplay(row.workPhone,row.workPhoneExtension);
function openProfile(row){profile.value={id:row.id,agencyId:row.agencyId||props.agencyId};}
function message(row){profile.value=null;emit('message',{id:row.id,name:row.displayName||row.name,agencyId:row.agencyId||props.agencyId});}
function email(value){profile.value=null;emit('compose-email',value);}
async function load(force=false){if(!props.visible||!props.sessionToken||(!force&&Date.now()-loadedAt<60000))return;const current=++version;loading.value=true;error.value='';const results=await Promise.allSettled([axios.get(`${props.apiBase}/directory`,{...config(),params:{agencyId:'all'}}),axios.get(`${props.apiBase}/contacts`,config())]);if(current!==version)return;for(let i=0;i<results.length;i++){const result=results[i];if(result.status==='fulfilled'){if(i===0)data.value=result.value.data;else saved.value=result.value.data.contacts||[];}else{if([401,403,423].includes(result.reason.response?.status)){data.value={providers:[],schoolStaff:[],agencies:[]};saved.value=[];}error.value=result.reason.response?.data?.error?.message||'Your contacts could not be loaded.';}}if(results.every(result=>result.status==='fulfilled'))loadedAt=Date.now();loading.value=false;}
watch(()=>props.visible,value=>{if(value)void load();},{immediate:true});watch(()=>props.initialSuite,value=>suite.value=value);watch(()=>props.sessionToken,()=>{version++;loadedAt=0;data.value={providers:[],schoolStaff:[],agencies:[]};saved.value=[];profile.value=null;void load();});onBeforeUnmount(()=>version++);
</script>
<template><section class="mobile-people" aria-label="Your people"><nav class="people-toolbar"><button v-for="tab in [{id:'providers',label:'Providers'},{id:'school_staff',label:'School staff'},{id:'saved',label:'Saved'}]" :key="tab.id" :aria-pressed="suite===tab.id" @click="suite=tab.id">{{tab.label}}</button><button :aria-expanded="searchOpen" @click="searchOpen=!searchOpen"><Search :size="15"/>Search</button></nav><div v-if="searchOpen" class="people-search"><input v-model="query" type="search" aria-label="Search people" placeholder="Name, credentials, school, or email"/><select v-if="agencies.length>1" v-model="agency" aria-label="Filter people by agency"><option value="">All agencies</option><option v-for="option in agencies" :key="option.id" :value="option.id">{{option.name}}</option></select></div><p v-if="loading&&!rows.length" role="status">Loading your people…</p><p v-if="error" role="alert">{{error}} <button @click="load(true)">Try again</button></p><template v-if="suite!=='saved'"><article v-for="person in rows" :key="`${person.agencyId}:${person.id}:${person.schoolId||''}`" class="person-row"><button class="photo-button" :aria-label="`View ${person.displayName}`" @click="openProfile(person)"><MobileIdentityAvatar :photo="person.profilePhotoUrl" :agency-icon="person.agencyLogoUrl" :name="person.displayName"/></button><div class="person-content"><div class="person-title"><button class="person-name" @click="openProfile(person)">{{person.displayName}}</button><span v-if="person.credential" class="person-credential">{{person.credential}}</span><span v-if="person.isSchoolAdmin" class="school-admin">SCHOOL ADMIN</span><a v-if="person.workPhoneExtension&&phone(person).telHref" :href="phone(person).telHref">Ext. {{person.workPhoneExtension}}</a></div><button v-if="person.email" class="person-email" @click="email({to:person.email})">{{person.email}}</button><small>{{person.schoolName||person.agencyName}}</small></div><button class="message-button" @click="message(person)"><MessageSquare :size="15"/><span>Message</span></button></article></template><template v-else><div class="saved-tools"><small>External contacts you saved.</small><button @click="emit('add-contact')">Add contact</button></div><article v-for="contact in rows" :key="contact.id" class="person-row"><MobileIdentityAvatar :name="contact.displayName||contact.name||contact.email"/><div class="person-content"><strong>{{contact.displayName||contact.name||contact.email}}</strong><button v-if="contact.email" class="person-email" @click="email({to:contact.email})">{{contact.email}}</button></div></article></template><p v-if="!loading&&!error&&!rows.length" class="empty">{{suite==='saved'?'No external contacts saved.':'No matching people in your affiliated directory.'}}</p><MobilePersonProfile v-if="profile" :api-base="apiBase" :session-token="sessionToken" :person-id="profile.id" :agency-id="profile.agencyId" @close="profile=null" @message="message" @compose-email="email"/></section></template>
<style scoped>
.mobile-people{font:14px/1.45 system-ui;color:#203b5b;background:#fff;border:1px solid #dce5f2;border-radius:16px;min-width:0;max-width:100%;overflow:hidden}.mobile-people button,.mobile-people a{font:inherit;color:#2b527d}.mobile-people button{border:1px solid #d8e2f1;border-radius:10px;background:#f4f7fd;padding:9px;min-height:40px;display:inline-flex;align-items:center;justify-content:center;gap:5px;cursor:pointer;user-select:none;-webkit-user-select:none}.people-toolbar{display:flex;gap:4px;padding:12px;overflow:auto}.people-toolbar button{white-space:nowrap;flex-shrink:0;border:0;background:none;font-weight:600}.people-toolbar [aria-pressed=true]{background:#edf3ff;color:#2058d8}.people-search{display:flex;gap:8px;padding:0 12px 12px;flex-wrap:wrap}.people-search input,.people-search select{font:16px system-ui;border:1px solid #cad8eb;border-radius:9px;padding:10px;min-width:0;max-width:100%;box-sizing:border-box;flex:1}.people-search input{flex-basis:220px}.person-row{display:flex;align-items:center;gap:12px;padding:18px 14px;border-top:1px solid #e6edf6;min-width:0}.person-content{min-width:0;flex:1}.person-title{display:flex;flex-wrap:wrap;align-items:baseline;column-gap:.35em;row-gap:2px}.person-title .person-name,.photo-button,.person-email{background:none!important;border:0!important;padding:0!important;min-height:0!important;text-align:left;justify-content:flex-start!important}.person-name{font-weight:700!important;color:#203b5b!important}.person-title .person-name{display:inline!important}.person-credential{font-weight:600;font-size:12px}.person-title>a{font-size:12px;font-weight:600;white-space:nowrap}.person-content .person-email{display:block!important;max-width:100%;overflow-wrap:anywhere;color:#52749d;margin-top:4px;font-size:12px}.person-content small{display:block;color:#778ba6;margin-top:5px;font-size:12px}.school-admin{font-size:10px;font-weight:700;letter-spacing:.04em}.mobile-people .message-button{background:#245cdb;color:#fff;border-color:#245cdb;font-size:12px;flex-shrink:0}.saved-tools{padding:8px 14px 14px;display:flex;justify-content:space-between;gap:8px;align-items:center}.empty,.mobile-people>p{padding:15px;color:#6f829d}:focus-visible{outline:3px solid #80a7ed;outline-offset:2px}@media(max-width:370px){.person-row{gap:8px;padding:16px 10px}.message-button span{display:none}}
</style>
